<?php

declare(strict_types=1);

namespace App\Models;

use App\Support\Ids\HasPrefixedId;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Support\Carbon;

/* @properties-start (generated by dev:model-docs) */
/**
 * @property string $id
 * @property string $user_id
 * @property string $name
 * @property string|null $for_person
 * @property bool $is_default
 * @property string $unit
 * @property string|null $jacket
 * @property string|null $collar
 * @property string|null $sleeve
 * @property string|null $waist
 * @property string|null $inseam
 * @property string|null $shoe
 * @property string|null $bag
 * @property string|null $apparel
 * @property array|null $preferences
 * @property int $orders_used_on
 * @property Carbon|null $created_at
 * @property Carbon|null $updated_at
 */
/* @properties-end */
class FitKitProfile extends Model
{
    use HasPrefixedId;

    protected static string $idPrefix = 'fit';

    protected $fillable = [
        'user_id', 'name', 'for_person', 'is_default', 'unit', 'jacket', 'collar', 'sleeve', 'waist', 'inseam',
        'shoe', 'bag', 'apparel', 'preferences', 'orders_used_on',
    ];

    protected function casts(): array
    {
        return [
            'is_default' => 'boolean',
            'preferences' => 'array',
        ];
    }

    /** @return BelongsTo<User, $this> */
    public function user(): BelongsTo
    {
        return $this->belongsTo(User::class);
    }
}
